"""Colon detector for layers.15.mlp.down_proj component 5582.

This component's activation is mostly diffuse, small noise (std about 0.35) with no
clear token or topic signature. Its one readable feature is that it goes negative on
colons: any token containing ":" or the full-width "：" (":", ":\n", "):", '":', " :").
The average colon gives about -0.8. The colon is more negative after a word about an
error, warning or failure ("Error:", "Warning:", "FAILED:", "Tests:"), about -1.6. It is
only mildly negative after a file extension (".py:"), about -0.3, and after a bare
number (a time such as "10:30"), about -0.6. Every other token predicts 0, the
component's mean, and the first token of a document predicts 0.
"""

READS = ()

ERROR_WORDS = {
    "Error", "error", "ERROR", "Errors", "Warning", "warning", "FAILED", "FAIL",
    "FAILURE", "Failed", "failed", "fail", "Fail", "Tests", "Suites", "problem",
    "TypeError", "Exception",
}
FILE_EXTENSIONS = {".py", ".js", ".ts", ".go", ".rs", ".java", ".php", ".h", ".c", ".cpp", ".rb", ".cs"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if ":" not in token and "：" not in token:
        return carry, 0.0
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    before = prefix.token_strings[-2].strip()
    if before in ERROR_WORDS:
        value = -1.6
    elif before in FILE_EXTENSIONS:
        value = -0.3
    elif before.isdigit():
        value = -0.6
    else:
        value = -0.8
    return carry, value

"""Layer 15 MLP down-projection, component 5587 (p-82af68dd@100000).

What it does: a word-level detector for "beneficiary / recipient / purpose" words.
  * "for" is the strongest trigger, and its translations (pour, para, für, для,
    Chinese 为 / 为了 / 对于) also fire. Sentence-initial "For" fires more than "for".
  * "to" fires weakly; sentence-initial "To" fires more.
  * verbs of giving, providing, helping, serving and offering fire moderately.
  * "per" ("per cent", "per day") fires moderately.
Every other token predicts 0. The prediction looks only at the current token.

Not modelled: within "for", the size and sign vary with context (for example, "for"
in prose such as "for years" runs high, and "for" in code comments runs negative), and
about half the variance is small background noise on ordinary tokens.
"""

READS = ()

# Each value is the mean activation of that group in a training sample.
FOR_TRANSLATIONS = {"pour", "para", "für", "для", "por", "voor"}
FOR_CHINESE = {"为", "為", "爲", "为了", "对于"}
GIVING_VERBS = {"give", "gives", "giving", "gave", "provide", "provides", "providing",
                "help", "helps", "helping", "serve", "serves", "serving", "offer", "offers"}


def predict(word):
    """Activation predicted for one token, given the token's text on its own."""
    lower = word.lower()
    capitalised = word[:1].isupper()
    if lower == "for":
        return 13.0 if capitalised else 7.2
    if lower in FOR_TRANSLATIONS:
        return 5.5
    if lower in FOR_CHINESE:
        return 10.4
    if lower == "to":
        return 5.3 if capitalised else 1.5
    if lower == "per":
        return 3.5
    if lower in GIVING_VERBS:
        return 4.0
    return 0.0


def step(carry, prefix, upstream):
    return carry, predict(prefix.token_strings[-1].strip())


if __name__ == "__main__":
    # A demonstration on one sentence: print each word with its predicted activation.
    sentence = "We cooked dinner for the guests, and then we gave them a gift to take home."
    for word in sentence.split():
        print(f"{word:>10}  {predict(word.strip('.,')):5.1f}")

"""Layer 15 MLP neuron 5588, which this component mostly reads (its V weight on that hidden unit is 0.8).

In plain terms, it tracks sentences. (1) It opens a sentence's subject: high on the first word of a
sentence when that word is a subject pronoun or demonstrative ("These", "Such", "This", "They", "He",
"It"), a determiner ("The", "A") or a discourse opener ("In", "Among", "Note", "Also"), and high on the
word right after such an opener ("This [is]", "In [particular]", "The [results]"). Both are stronger the
longer the sentence before them was. Other sentence-opening words, including conjunctions ("But",
"So", "Since"), stay small. (2) It marks sentence ends: a period that closes a sentence (also when
followed by a line break) is positive, more so the longer the sentence has run. Commas sit a little
below zero. Everything else is near zero. Only the words and their place in the sentence are used.
"""

READS = ()

SUBJECT = frozenset("These Such This That Those They He She It Its Their His Her We You I".split())
DETERMINER = frozenset("The A An Each Both Most Every Some Many All".split())
OPENER = frozenset("Note Also Additionally In Among According Even Of For However Moreover Finally Here There".split())
CONJUNCTION = frozenset("But Since Given While And So Perhaps Maybe What How When If Then Now".split())

# activation at a sentence's first word and at the word after it, by class of the first word
FIRST = {"subject": 2.5, "determiner": 2.0, "opener": 1.4, "conjunction": 0.1, "other": 0.3}
SECOND = {"subject": 1.0, "determiner": 1.0, "opener": 0.8, "conjunction": -0.1, "other": 0.1}
LONG = 40  # sentence length, in tokens, at which a closing period reaches its full value


def opener_class(raw):
    word = raw.strip()
    for name, words in (("subject", SUBJECT), ("determiner", DETERMINER), ("opener", OPENER),
                        ("conjunction", CONJUNCTION)):
        if word in words:
            return name
    return "other"


def ends_sentence(raw):
    return raw.rstrip(" ").endswith((".", "!", "?", "。")) or raw.endswith("\n")


def gain(previous_length):
    """How much the openers of a sentence grow with the length of the sentence before it."""
    return 0.5 + min(previous_length, 30) / 30


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None:
        return (0, "other", doc, raw, 0), 0.0  # the row's first token
    k, cls, last_doc, last_raw, previous = carry
    if doc != last_doc or ends_sentence(last_raw):
        previous = k + 1 if doc == last_doc else 0  # length of the sentence that just ended
        k, cls = 0, opener_class(raw)  # a new sentence opens with this token
    else:
        k += 1
    if raw.rstrip().endswith((".", "。")) and k > 0:
        value = min(k, LONG) / LONG  # a closing period, more so after a long sentence
    elif k == 0:
        value = FIRST[cls] * gain(previous)
    elif k == 1:
        value = SECOND[cls] * gain(previous)
    elif raw.strip() == ",":
        value = -0.2
    else:
        value = 0.0
    return (k, cls, doc, raw, previous), value

"""Causative verbs ("bring about an effect"): the component fires on verbs such as
"bring", "induce", "cause", "make", "lead", "promote", and their Chinese
counterparts (引发 "trigger", 带动 "lead along", 推动 "push forward", 让 "let/make").
It is strongest on "bring" (about 15), weaker on "cause"/"make" (about 3), and
weakly on the determiner that opens the verb's object ("bring the": about 40% of
the verb's value). Everything else predicts 0, and the first token of a document
predicts 0. The strengths are the average activations of each word in the training
data, rounded to a few tiers.

The rest of the component's variance (most of it) is diffuse, small values on
ordinary tokens, and is not captured here.
"""

READS = ()

BRING = {"bring", "brings", "brought", "bringing"}
STRONG = {"induce", "induced", "induces", "inducing", "invite", "invited",
          "invites", "inviting", "provoke", "provoked", "spark", "sparked",
          "summon", "attract", "attracting", "trigger", "triggered", "triggers",
          "引发", "引起", "带动", "带领", "引领", "邀请", "吸引", "惹", "拉动", "带来"}
CAUSE = {"cause", "causes", "caused", "causing", "make", "makes", "made",
         "making", "lead", "led", "leads", "leading", "promote", "promoted",
         "promoting", "raise", "raised", "raises", "raising", "carry",
         "carried", "carries", "carrying", "pull", "pulled", "pulling",
         "introduce", "introduced", "introduces", "encourage", "encourages",
         "推动", "引", "带", "让", "讓", "逼"}
WEAK = {"create", "creates", "created", "creating", "keep", "kept", "call",
        "called", "calling", "ask", "asked", "send", "produce", "generate",
        "take", "took", "hold", "held"}
DETERMINERS = {"the", "a", "an", "their", "your", "his", "her", "its", "my",
               "our", "this", "these", "those", "some", "each", "every", "all",
               "it", "them", "him", "me", "us", "you"}


def strength(token):
    word = token.strip().lower()
    if word in BRING:
        return 15.0
    if word in STRONG:
        return 7.0
    if word in CAUSE:
        return 3.0
    if word in WEAK:
        return 1.5
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if word in DETERMINERS:
        return carry, 0.4 * strength(prefix.token_strings[-2])
    return carry, strength(word)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:5596 (layer 15 MLP down-projection).

What it does, in plain terms. Almost all of this component's activation is a weak, diffuse
signal (std about 0.3) that does not follow the token: the same word gets different values in
different places, and the activation looks the same whether or not a token repeats earlier in
the text. Its rare large values have two clearer tendencies:
  - number words (one, two, three, twice, ...) push it negative, on average about -0.12;
  - words about error or confusion (wrong, mistake, confusing, ...) push it positive, about +0.12.
Everywhere else the program predicts the component's typical value, about -0.03.
"""

READS = ()

BASELINE = -0.03

NUMBER_WORDS = {
    "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
    "ten", "eleven", "twelve", "once", "twice", "thrice",
}
ERROR_WORDS = {
    "wrong", "mistake", "mistakes", "error", "errors", "incorrect", "confusing",
    "confused", "confusion", "misunderstanding", "disagree",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in NUMBER_WORDS:
        return carry, -0.12
    if word in ERROR_WORDS:
        return carry, 0.12
    return carry, BASELINE

"""Predicts component p-82af68dd@100000/layers.15.mlp.down_proj:5597, one rank-one piece of
layer 15's MLP down projection.

What it reads: MLP hidden unit 5597 of layer 15, its largest input weight (about 43% of the
input direction's length), plus many small weights on other hidden units.
What it writes: its output direction, read through the tied embeddings, tilts the next-token
distribution toward hedges ("seems", "supposedly", "似乎") and away from praise adjectives
("beautiful", "magnificent"). Its activation is small and diffuse: a full per-token lookup table explains
only about 3% of its variance on held-out text, and it never passes the causal-importance
threshold, so this program gives coarse word-class levels only.

What the program does, from the newest token alone:
  - the first token of a row: 0 (the component is silent there);
  - "also" and its translations: strongly negative;
  - function words and hedges ("to", "this", "would", "which", "maybe", ...): mildly negative;
  - closing brackets and quotes: mildly positive;
  - anything else: the component's typical level, slightly negative.
"""

READS = ()

ALSO_WORDS = {" also", " Also", "also", "也", "也是", "も", "도", "também", "auch", "también", "aussi", "также"}
FUNCTION_AND_HEDGE = {
    " to", " this", " would", " which", " we", " was", " will", " I", " you", " is", " been",
    " have", " there", " can", " could", " might", " may", " perhaps", " maybe", " seems", " seem",
}
CLOSERS = {")", "]", "}", '"', "”", '"]', ")\n", "}\n"}

ALSO_LEVEL = -0.45
FUNCTION_LEVEL = -0.10
CLOSER_LEVEL = 0.04
REST_LEVEL = -0.03


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return carry, 0.0
    word = prefix.token_strings[-1]
    if word in ALSO_WORDS:
        value = ALSO_LEVEL
    elif word in FUNCTION_AND_HEDGE:
        value = FUNCTION_LEVEL
    elif word in CLOSERS:
        value = CLOSER_LEVEL
    else:
        value = REST_LEVEL
    return carry, value

"""Layer 15, MLP hidden unit 5607, as written into the residual stream.

The component reads only that one unit of the MLP's hidden activations (its input
direction is almost exactly that unit), so its activation is that unit's value, signed,
scaled by the write direction's norm. It is large on whitespace and line breaks, in code
and in hard-wrapped legal or prose text, and small on words and digits. Both signs occur
on the same kinds of token.

What this program captures is only the typical value of each kind of token:

- an open bracket at the end of a line, "(\n" (a call whose arguments start on the next
  line): strongly negative;
- odd spaces (non-breaking space, NUL, zero-width space): negative;
- a run of spaces or tabs inside a line (indentation): slightly positive;
- a line break together with text, such as ":\n": slightly positive;
- anything else: 0.

Measured: the current token alone explains about 4-5% of its variance and a 16-token
window model about 6%; column, indentation depth and how code-like the context is add
nothing to the sign. This program explains about 2% (variance explained on eval).
A lookup table of per-token means would add little more; the sign is what is missing.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

ODD_SPACES = {"\xa0", "\x00", "​"}


def kind_value(text: str) -> float:
    """Typical activation of one token, given the token alone."""
    if "(" in text and "\n" in text:
        return -1.3
    if text in ODD_SPACES:
        return -1.9
    if text.strip() == "":
        if "\n" in text:
            return 0.0
        return -0.07 if text == " " else 0.3
    if "\n" in text:
        return 0.12
    return 0.0


def step(carry, prefix, upstream: Mapping):
    """The activation at the newest token of the prefix."""
    return carry, float(kind_value(prefix.token_strings[prefix.position]))

"""Layer 15, MLP hidden unit 5610 (down_proj component 5610), read on its own.

This component is one MLP neuron: its input direction is that unit alone (up to small
terms), so its activation is essentially the unit's value. It is mostly near zero, with
a heavy negative tail on a few kinds of token, nearly all of them opening a mathematical
or function-call expression:

- tokens that open a parenthesised or bracketed term right after a symbol, such as
  "*(", "/(", ")(", "}(", "(\\" and "left", or a named function such as " sin", " cos",
  " sqrt", " ln", " exp", " log": strongly negative;
- a bare "(" and a subscript opener "_{": negative;
- a single-letter function name " f" or " g": mildly negative;
- prepositions that open a rate, range or time phrase, such as " per", " for",
  " between", " during", " against", " over": mildly negative;
- the common words " of", " is", " as" and " =": slightly positive.

Every other token is predicted as 0. The values are least-squares fits to the
component's activations on training text. The rule explains about 2% of the variance
(Pearson r about 0.15): most of the activation is spread over ordinary tokens in a way a
short token list does not capture. A table of about 1000 per-token means would reach
about 4-5%, and per-bigram means about 9%, at the cost of readability.
"""

READS = ()

OPENERS = {"*(", "/(", ")(", "}(", ")/(", ")*(", "(\\", "{(", "[(", "(x", "left",
           " sin", "sin", " cos", "cos", " tan", " sqrt", "sqrt", " ln", " exp", "exp",
           " log", "log"}
BARE_PAREN = {"("}
SUBSCRIPT = {"_{"}
FUNCTION_LETTERS = {" f", " g", "f", "g"}
PREPOSITIONS = {" for", " per", " between", " during", " against", " over", " across",
                " after", " when", " at", " on"}
COMMON_POSITIVE = {" of", " is", " as", " ="}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[prefix.position]
    if tok in OPENERS:
        value = -2.0
    elif tok in BARE_PAREN:
        value = -1.0
    elif tok in SUBSCRIPT:
        value = -1.5
    elif tok in FUNCTION_LETTERS:
        value = -0.45
    elif tok in PREPOSITIONS:
        value = -0.5
    elif tok in COMMON_POSITIVE:
        value = 0.2
    else:
        value = 0.0
    return carry, value

"""Counting-up numbers: a strong dip on the digit that completes "the next number".

Component p-82af68dd@100000/layers.15.mlp.down_proj:5615 (layer 15's MLP down projection)
sits near zero almost everywhere. Its clearest behaviour is on digits that finish a number
one larger than the number before it:

  * Line numbers of a listing. In code shown with line numbers, each line starts with its
    number and then a separator, and the numbers count up by one:

        643\tfunc ...
        644\t    {

    The final "4" of "644" drops to about -7.4, just before the tab. The earlier digits of
    the number stay near zero, as do digits that don't complete the count.
  * Numbered list items. "1. ... 2. ... 3." dips more weakly (about -2 for "."). Numbers
    that count up mid-line, such as "[2]" after "[1]", dip weakly too (about -1).

The program reads the text one token at a time and keeps:
  * prev_line and its mark: the last number that opened a line, and the character that
    ended it (tab, "|", ":", ")" or ".");
  * head: the text since the last newline, while it is only spaces and digits;
  * last_number: the last complete number anywhere, and the digits typed so far.
The model cannot see the mark after a digit, but the count tells it the number is complete.
A digit fires when head equals prev_line + 1 (a line number), or when its run of digits equals
last_number + 1 (a count-up mid-line). The dip size for a line number depends on its mark,
which the previous numbered line already shows.
"""

READS = ()  # this program reads no other component

DIGITS = "0123456789"

# Activation when a line number counts up, by the mark that ended the previous numbered line.
DROP_BY_MARK = {"\t": -7.4, "|": -5.5, ":": -5.5, ")": -3.6, ".": -2.1}
DROP_OTHER_MARK = -3.0
# Activation when a number mid-line is one more than the last number mentioned.
INLINE_DROP = -0.8


def step(carry, prefix, upstream):
    new_doc = len(prefix.document_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_doc:
        carry = {"prev": None, "mark": None, "head": "", "last": None, "run": ""}
    state = dict(carry)
    token = prefix.token_strings[-1]
    for ch in token:
        if ch in DIGITS:
            state["run"] += ch
        else:
            if state["run"]:
                state["last"] = int(state["run"])  # a number just ended
                state["run"] = ""
            if ch == "\n":
                state["head"] = ""  # a new line: its number, if any, starts here
            elif ch == " ":
                if state["head"] is not None:
                    state["head"] += ch
            else:
                if state["head"] and state["head"].strip().isdigit():
                    state["prev"] = int(state["head"].strip())  # the line number ended
                    state["mark"] = ch
                state["head"] = None  # not a line number until the next newline
        if ch in DIGITS and state["head"] is not None:
            state["head"] += ch

    value = 0.0
    if token[-1:] in DIGITS:
        next_line = None if state["prev"] is None else str(state["prev"] + 1)
        next_number = None if state["last"] is None else str(state["last"] + 1)
        if state["head"] is not None and state["head"].strip() == next_line:
            value = DROP_BY_MARK.get(state["mark"], DROP_OTHER_MARK)
        elif state["run"] == next_number:
            value = INLINE_DROP
    return state, value

"""Layer 15 MLP hidden unit 5621 (the component's activation is almost all of this unit).

It goes negative in narrative text where the next word is likely to be a past-tense
event verb (often a passive or outcome verb: "was [released]", "but [he] couldn't",
"until [...]", "eventually [cancelled]"). Its output direction, when negative, promotes
outcome verbs such as "cancelled", "aborted", "scrapped" and "eventually".

This program is a cue list, not a model of the neuron. It gives a fixed negative value
to a few cue tokens and zero elsewhere:
  - the chat role name "user" right after a turn-start marker (strongest),
  - contrast and time connectives: but, however, until, before, later, eventually,
  - past auxiliaries: was, were, had,
  - third-person subject pronouns: he, she, they.
Values are the mean activations of those cue groups on training rows. Most of the
variance is not captured by any token-level rule.
"""

READS = ()

CHAT_ROLE_AFTER_TURN_START = -3.5
CONTRAST_TIME = {" but", " But", " However", " however", " until", " before", " later", " eventually", " finally"}
PAST_AUX = {" was", " were", " had"}
SUBJECT_3RD = {" he", " He", " she", " She", " they", " They"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok == "user" and prev == "<|im_start|>":
        value = CHAT_ROLE_AFTER_TURN_START
    elif tok in CONTRAST_TIME:
        value = -1.1
    elif tok in PAST_AUX:
        value = -0.95
    elif tok in SUBJECT_3RD:
        value = -0.75
    else:
        value = 0.0
    return carry, float(value)
